def _unpack(chunks: tuple[bytes, ...], expected_sha256: str) -> str:
    raw = zlib.decompress(base64.b85decode(b"".join(chunks)))
    actual = hashlib.sha256(raw).hexdigest().upper()
    if actual != expected_sha256:
        raise RuntimeError(f"embedded resource checksum mismatch: {actual}")
    return raw.decode("utf-8")


def load_payload(path: Path) -> dict[str, Any]:
    with path.open("r", encoding="utf-8") as handle:
        payload = json.load(handle)
    if not isinstance(payload, dict):
        raise ValueError("render payload top level must be a JSON object")
    required = ("meta", "people", "daily", "weekly", "monthly", "stock_drilldowns")
    missing = [key for key in required if key not in payload]
    if missing:
        raise ValueError(f"render payload missing fields: {', '.join(missing)}")
    if len(payload.get("people", [])) != 10:
        raise ValueError("render payload must contain exactly 10 tracked accounts")
    if payload.get("meta", {}).get("tracked_account_count") != 10:
        raise ValueError("render payload must contain exactly 10 tracked accounts")
    ids = [str(person.get("blogger_id", "")) for person in payload["people"]]
    if len(set(ids)) != 10 or "" in ids:
        raise ValueError("people must contain 10 unique blogger_id values")
    for person in payload["people"]:
        if not str(person.get("avatar_data_uri", "")).startswith("data:image/"):
            raise ValueError(f"avatar is not embedded for {person.get('blogger_id')}")
    for symbol, detail in payload["stock_drilldowns"].items():
        if detail.get("default_person_window") != "days_7":
            raise ValueError(f"{symbol}: default_person_window must be days_7")
        for key in ("today", "days_7", "days_28"):
            rows = detail.get("people_by_window", {}).get(key, [])
            if len(rows) != 10:
                raise ValueError(f"{symbol}.{key} must contain exactly 10 people")
    return payload


def _json_for_script(payload: dict[str, Any]) -> str:
    text = json.dumps(payload, ensure_ascii=False, separators=(",", ":"), sort_keys=True)
    return text.replace("</", "<\\/").replace("<!--", "<\\!--")


def _pack_html(html: str) -> str:
    packed = gzip.compress(html.encode("utf-8"), compresslevel=9, mtime=0)
    encoded = base64.b64encode(packed).decode("ascii")
    return f"""<!DOCTYPE html>
<html lang="zh-CN">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<style>html,body{{margin:0;min-height:100%;background:#f7f6f0}}</style>
</head>
<body>
<script id="packedDashboard" type="application/octet-stream">{encoded}</script>
<script>
(async()=>{{
  try{{
    if(typeof DecompressionStream!=="function"){{
      throw new Error("当前浏览器不支持打开压缩版 Dashboard，请使用最新版 Chrome 或 Edge。");
    }}
    const encoded=document.querySelector("#packedDashboard").textContent.trim();
    const binary=atob(encoded);
    const bytes=new Uint8Array(binary.length);
    for(let i=0;i<binary.length;i+=1)bytes[i]=binary.charCodeAt(i);
    const stream=new Blob([bytes]).stream().pipeThrough(new DecompressionStream("gzip"));
    const html=await new Response(stream).text();
    document.open();
    document.write(html);
    document.close();
  }}catch(error){{
    document.body.innerHTML='<main style="max-width:720px;margin:80px auto;padding:24px;font:16px/1.7 system-ui;color:#222;background:#fff;border:1px solid #ddd">'+String(error&&error.message||error)+'</main>';
  }}
}})();
</script>
</body>
</html>
"""


def render(input_path: Path, output_path: Path) -> None:
    payload = load_payload(input_path)
    template = _unpack(_FINAL_UI_B85, FINAL_UI_SHA256)
    runtime = _unpack(_RUNTIME_B85, RUNTIME_SHA256)
    overflow_guard = (
        '<style id="productionOverflowGuard">'
        'html,body{max-width:100%;overflow-x:hidden}'
        '.quarter-grid{max-width:100%;overflow-x:auto;overscroll-behavior-x:contain}'
        '</style>\n'
    )
    if "</head>" not in template:
        raise RuntimeError("embedded final UI is missing </head>")
    template = template.replace("</head>", overflow_guard + "</head>", 1)
    injection = (
        '<script id="dashboardPayload" type="application/json">'
        + _json_for_script(payload)
        + "</script>\n<script>"
        + runtime
        + "</script>\n"
    )
    if "</body>" not in template:
        raise RuntimeError("embedded final UI is missing </body>")
    html = template.replace("</body>", injection + "</body>", 1)
    output_path.parent.mkdir(parents=True, exist_ok=True)
    output_path.write_text(_pack_html(html), encoding="utf-8", newline="\n")


def main() -> int:
    parser = argparse.ArgumentParser(description="Render the locked 10V UI into one self-contained HTML file")
    parser.add_argument("--input", required=True, type=Path, help="dashboard payload JSON")
    parser.add_argument("--output", required=True, type=Path, help="final HTML path")
    parser.add_argument("--source-info", action="store_true", help="print embedded UI/runtime checksums")
    args = parser.parse_args()
    if args.source_info:
        print(json.dumps({"final_ui_sha256": FINAL_UI_SHA256, "runtime_sha256": RUNTIME_SHA256}, indent=2))
    render(args.input.resolve(), args.output.resolve())
    print(args.output.resolve())
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
